#!/usr/bin/env node
// VFX building blocks for Niagara: procedural textures, the master VFX material, its instances, and a mesh set.
// Everything here is generated by code during the jam, so it is the game's own content.
//
//   node gen/vfx/vfx.ts textures [--size 512] [--only T_VFX_Spark,T_VFX_Noise] [--no-unreal]
//   node gen/vfx/vfx.ts master [--force]
//   node gen/vfx/vfx.ts instance <Name> '<json spec>'        e.g.
//        node gen/vfx/vfx.ts instance HitSpark '{"additive":true,"textures":{"MaskTexture":"/Game/Kit/VFX/Textures/T_VFX_Spark"},"scalars":{"EmissiveStrength":15}}'
//   node gen/vfx/vfx.ts meshes [--no-unreal]
//   node gen/vfx/vfx.ts flipbook /Game/FX/NS_Fire_BakedAtlas_Texture2D_0   (after a Baker bake: Clamp, colour, save)
//   node gen/vfx/vfx.ts all                                   (textures + master + meshes)
//   --out <dir> writes the files there instead of <project>\Generated\vfx\ (with --no-unreal: no project needed)
// Files go to <project>\Generated\vfx\; assets to /Game/Kit/VFX/{Textures,Materials,Meshes}. Re-runs re-import textures
// in place (references survive); a mesh that effects already use is kept as is. Material parameters and spec keys: gen/unreal/py/build_vfx_material.py header; recipes and
// how to wire them in Niagara: docs/ue/vfx.md "Kit VFX building blocks".
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { parseArgs } from 'node:util';
import { KIT, errorMessage, fail, generatedDir, isMain, jsonArg } from '../paths.ts';
import { parseMarkedJson, run } from '../proc.ts';
import { McpUnreachableError, callTool, mcpCall, type ObjectRef } from '../unreal/mcp.ts';
import { runPythonFileOrThrow } from '../unreal/python.ts';
import { VFX_TEXTURES, writeGrayPng } from './textures.ts';

const MT = 'megajam_tools.toolsets.MegajamTools';
const OB = 'editor_toolset.toolsets.object.ObjectTools';
const SM = 'editor_toolset.toolsets.static_mesh.StaticMeshTools';
const AS = 'editor_toolset.toolsets.asset.AssetTools';
export const VFX_ROOT = '/Game/Kit/VFX';
export const VFX_MASTER = `${VFX_ROOT}/Materials/M_VFX_Master`;
const TEX = `${VFX_ROOT}/Textures`;
const PY = (f: string): string => join(KIT, 'gen', 'unreal', 'py', f);

/** Imports (or re-imports in place) one file with MegajamTools.import_any; returns the first object. */
async function importOne(folder: string, name: string, file: string): Promise<ObjectRef> {
  const r = await callTool<ObjectRef[] | ObjectRef>(MT, 'import_any', { folder_path: folder, asset_name: name, source_file: file.replace(/\\/g, '/'), replace: true });
  const obj = Array.isArray(r) ? r[0] : r;
  if (!obj) throw new Error(`import produced nothing: ${file}`);
  return obj;
}

export async function makeTextures(o: { size?: number; only?: string[]; unreal?: boolean; out?: string } = {}): Promise<string[]> {
  const size = o.size ?? 512;
  const dir = o.out ?? join(generatedDir('vfx'), 'textures');
  mkdirSync(dir, { recursive: true });
  const list = VFX_TEXTURES.filter((t) => !o.only || o.only.includes(t.name));
  if (o.only && list.length !== o.only.length) fail(`unknown texture in --only; known: ${VFX_TEXTURES.map((t) => t.name).join(', ')}`);
  const done: string[] = [];
  for (const t of list) {
    const file = join(dir, `${t.name}.png`);
    writeGrayPng(file, size, t.render(size));
    if (o.unreal !== false) {
      const tex = await importOne(TEX, t.name, file);
      const addr = t.tiles ? 'TA_Wrap' : 'TA_Clamp';
      await mcpCall(OB, 'set_properties', {
        instance: tex,
        values: JSON.stringify({ SRGB: false, CompressionSettings: 'TC_Masks', LODGroup: 'TEXTUREGROUP_Effects', AddressX: addr, AddressY: addr }),
      });
    }
    console.log(`  ${t.name}  ${t.tiles ? 'tiles' : 'clamped'}  ${t.what}`);
    done.push(`${TEX}/${t.name}`);
  }
  // Never save an empty list: save_assets([]) saves every dirty package, the user's level included.
  if (o.unreal !== false && done.length) {
    if (!(await callTool<boolean>(AS, 'save_assets', { asset_paths: done }))) throw new Error('saving the textures failed');
  }
  return done;
}

export interface VfxMasterResult { path: string; version: string; rebuilt: boolean; expressions?: number }

export async function ensureVfxMaster({ force = false }: { force?: boolean } = {}): Promise<VfxMasterResult> {
  const need = ['T_VFX_SoftCircle', 'T_VFX_Noise'];
  const missing: string[] = [];
  for (const n of need) if (!(await callTool<boolean>(AS, 'exists', { path: `${TEX}/${n}` }))) missing.push(n);
  if (missing.length) await makeTextures({ only: missing });
  const r = parseMarkedJson<VfxMasterResult>(
    await runPythonFileOrThrow(PY('build_vfx_material.py'), {
      path: VFX_MASTER, tex_mask: `${TEX}/T_VFX_SoftCircle`, tex_noise: `${TEX}/T_VFX_Noise`, ...(force ? { force: '1' } : {}),
    }),
    'VFXMASTER_JSON');
  return r;
}

export async function makeInstance(name: string, spec: Record<string, unknown>): Promise<unknown> {
  await ensureVfxMaster();
  return parseMarkedJson<unknown>(
    await runPythonFileOrThrow(PY('build_vfx_instance.py'), {
      path: `${VFX_ROOT}/Materials/MI_VFX_${name}`, parent: VFX_MASTER, spec: JSON.stringify(spec),
    }),
    'VFXMI_JSON');
}

/**
 * Prepares a Flipbook Baker sheet for M_VFX_Master's FlipbookColorTexture: the Baker writes an RGBA16F HDR texture
 * with Wrap addressing (its own address setting doesn't reach the asset). Clamp stops neighbouring frames bleeding in;
 * sRGB colour compression matches the parameter's Color sampler (values above 1 clip: EmissiveStrength restores glow).
 */
export async function prepareFlipbook(texturePath: string): Promise<string> {
  const objectPath = texturePath.includes('.') ? texturePath : `${texturePath}.${texturePath.split('/').pop()}`;
  await mcpCall(OB, 'set_properties', {
    instance: { refPath: objectPath },
    values: JSON.stringify({ SRGB: true, CompressionSettings: 'TC_Default', LODGroup: 'TEXTUREGROUP_Effects', AddressX: 'TA_Clamp', AddressY: 'TA_Clamp' }),
  });
  const pkg = objectPath.split('.')[0]!;
  if (!(await callTool<boolean>(AS, 'save_assets', { asset_paths: [pkg] }))) throw new Error(`saving ${pkg} failed`);
  return pkg;
}

interface MeshJson { out: string; meshes: { name: string; file: string; tris: number }[] }

export async function makeMeshes(o: { unreal?: boolean; out?: string } = {}): Promise<MeshJson> {
  const dir = o.out ?? join(generatedDir('vfx'), 'meshes');
  mkdirSync(dir, { recursive: true });
  const r = parseMarkedJson<MeshJson>(
    await run('blender', ['-b', '--factory-startup', '--python', join(KIT, 'gen', 'blender', 'vfx_meshes.py'), '--', dir], 'blender vfx_meshes'),
    'VFXMESH_JSON');
  for (const m of r.meshes) console.log(`  ${m.name}  ${m.tris} tris`);
  if (o.unreal === false) return r;
  const folder = `${VFX_ROOT}/Meshes`;
  const paths: string[] = [];
  for (const m of r.meshes) {
    let mesh: ObjectRef;
    try {
      mesh = await importOne(folder, m.name, m.file);
    } catch (e) {
      // A mesh that effects already use can't be re-imported in place (MegajamTools refuses): keep the existing one.
      if (!/is referenced/.test(errorMessage(e))) throw e;
      console.log(`  ${m.name}: kept the existing asset (referenced; rename or remove its users to regenerate it)`);
      continue;
    }
    // Particle meshes stay non-Nanite (docs/ue/vfx.md "Cost rules").
    await mcpCall(SM, 'set_nanite_enabled', { mesh, enabled: false });
    paths.push(`${folder}/${m.name}`);
  }
  // Every mesh kept (all referenced): nothing to save, and save_assets([]) would save every dirty package.
  if (paths.length && !(await callTool<boolean>(AS, 'save_assets', { asset_paths: paths }))) throw new Error('saving the meshes failed');
  return r;
}

if (isMain(import.meta.url)) {
  const { values: o, positionals } = parseArgs({
    allowPositionals: true,
    options: {
      size: { type: 'string', default: '512' },
      only: { type: 'string' },
      force: { type: 'boolean', default: false },
      'no-unreal': { type: 'boolean', default: false },
      out: { type: 'string' },
    },
  });
  const [cmd, a, b] = positionals;
  const unreal = !o['no-unreal'];
  const out = o.out ? { out: o.out } : {};
  try {
    if (cmd === 'textures') await makeTextures({ size: parseInt(o.size, 10) || 512, unreal, ...out, ...(o.only ? { only: o.only.split(',') } : {}) });
    else if (cmd === 'master') console.log(JSON.stringify(await ensureVfxMaster({ force: o.force })));
    else if (cmd === 'instance' && a) console.log(JSON.stringify(await makeInstance(a, b ? jsonArg<Record<string, unknown>>(b) : {})));
    else if (cmd === 'meshes') await makeMeshes({ unreal, ...out });
    else if (cmd === 'flipbook' && a) console.log(`prepared ${await prepareFlipbook(a)}`);
    else if (cmd === 'all') {
      await makeTextures({ size: parseInt(o.size, 10) || 512, unreal, ...(o.out ? { out: join(o.out, 'textures') } : {}) });
      if (unreal) console.log(JSON.stringify(await ensureVfxMaster({ force: o.force })));
      await makeMeshes({ unreal, ...(o.out ? { out: join(o.out, 'meshes') } : {}) });
    } else {
      console.log("usage: vfx.ts textures [--size 512] [--only A,B] [--no-unreal] | master [--force] | instance <Name> '<json>' (or '@spec.json') | meshes [--no-unreal] | flipbook <texture path> | all   (textures, meshes, all: [--out dir])");
      process.exit(2);
    }
  } catch (e) {
    if (e instanceof McpUnreachableError) fail(`${e.message} (files are written; use --no-unreal to skip the import)`);
    fail(errorMessage(e));
  }
}
